// Selected official application controller; generated by prepare_partner_detail_window_ui.py.
namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.WorldUI;
using MultiLanguageText = Zjcs.Official.WorldUI.WorldMultiLanguageText;
using System;
using System.Collections.Generic;
using UnityEngine;


public class SkeletonGraphicAnimSequence : MonoBehaviour
{
	[SerializeField]
	private Component mSkeletonGraphic;

	[SerializeField]
	private List<AppearanceAnimData> mAnimDataList = new List<AppearanceAnimData>();

	[SerializeField]
	private bool mPlayOnEnable = true;

    private Func<Component, IPartnerSequenceGraphic> resolve;
    private IPartnerSequenceGraphic Graphic => resolve(mSkeletonGraphic);
    public void Configure(Func<Component, IPartnerSequenceGraphic> value)
    { resolve = value ?? throw new ArgumentNullException(nameof(value)); }

	private int mIdx = -1;

	private int mLoopTimes;

	private float mEnterMixTimer;

	private bool mIsWaitPlayAnim;

	public Action<string> OnAnimStart;

	public Action<string> OnAnimEnd;

	private Action<IPartnerSequenceTrack> mOnAnimComplete;

	private Action<IPartnerSequenceGraphic> mOnAnimationRebuild;

	private Action<IPartnerSequenceTrack> OnAnimCompleteDelegate
	{
		get
		{




			Action<IPartnerSequenceTrack> val = mOnAnimComplete;
			if (val == null)
			{
				Action<IPartnerSequenceTrack> val2 = OnAnimComplete;
				Action<IPartnerSequenceTrack> val3 = val2;
				mOnAnimComplete = val2;
				val = val3;
			}
			return val;
		}
	}

	private Action<IPartnerSequenceGraphic> OnAnimationRebuildDelegate
	{
		get
		{




			Action<IPartnerSequenceGraphic> val = mOnAnimationRebuild;
			if (val == null)
			{
				Action<IPartnerSequenceGraphic> val2 = OnAnimationRebuild;
				Action<IPartnerSequenceGraphic> val3 = val2;
				mOnAnimationRebuild = val2;
				val = val3;
			}
			return val;
		}
	}

	private void OnEnable()
	{
		if (mPlayOnEnable)
		{
			Play();
		}
		RegisterSkeletonEvent();
	}

	private void OnDisable()
	{
		DeregisterSkeletonEvent();
		mIsWaitPlayAnim = false;
	}

	private void RegisterSkeletonEvent()
	{
		if ((Object)(object)mSkeletonGraphic != (Object)null)
		{
			IPartnerSequenceAnimationState animationState = Graphic.AnimationState;
			if (animationState != null)
			{
				animationState.Complete += OnAnimCompleteDelegate;
			}
			Graphic.OnAnimationRebuild += OnAnimationRebuildDelegate;
		}
	}

	private void DeregisterSkeletonEvent()
	{
		if ((Object)(object)mSkeletonGraphic != (Object)null)
		{
			IPartnerSequenceAnimationState animationState = Graphic.AnimationState;
			if (animationState != null)
			{
				animationState.Complete -= OnAnimCompleteDelegate;
			}
			Graphic.OnAnimationRebuild -= OnAnimationRebuildDelegate;
		}
	}

	private void OnAnimationRebuild(IPartnerSequenceGraphic animated)
	{
		IPartnerSequenceAnimationState animationState = Graphic.AnimationState;
		animationState.Complete -= OnAnimCompleteDelegate;
		animationState.Complete += OnAnimCompleteDelegate;
		if (mIsWaitPlayAnim)
		{
			Play();
		}
	}

	private void Update()
	{
		if (!(mEnterMixTimer <= 0f))
		{
			mEnterMixTimer -= Time.deltaTime;
			if (mEnterMixTimer <= 0f)
			{
				mEnterMixTimer = 0f;
				NextAnim();
			}
		}
	}

	private void OnAnimComplete(IPartnerSequenceTrack entry)
	{
		AppearanceAnimData curAnimData = GetCurAnimData();
		if (curAnimData.AnimName != entry.Animation.Name)
		{
			return;
		}
		mLoopTimes++;
		if (curAnimData.LoopTimes >= 0)
		{
			if (curAnimData.LoopTimes - mLoopTimes > 0)
			{
				PlayAnim(curAnimData, default);
			}
			else
			{
				NextAnim();
			}
		}
	}

	public void NextAnim()
	{
		if (mLoopTimes > 0)
		{
			mLoopTimes = 0;
			Graphic.AnimationState.ClearTrack(0);
			OnAnimEnd?.Invoke(GetCurAnimData().AnimName);
		}
		PlayAnim(mIdx + 1);
	}

	public void PlaySequence(List<AppearanceAnimData> sequence)
	{
		Stop();
		IPartnerSequenceSkeleton skeleton = Graphic.Skeleton;
		if (skeleton != null)
		{
			skeleton.SetToSetupPose();
		}
		mAnimDataList = sequence;
		Play();
	}

	public void Play()
	{
		if (mAnimDataList.Count == 0)
		{
			return;
		}
		if (Graphic.AnimationState == null)
		{
			mIsWaitPlayAnim = true;
			Debug.LogWarning("尝试播放动画时，Spine数据还未进行初始化，大概率是玩家数据还未下发就播放了动画，请将动画调用调整到正确的播放时机。");
		}
		else
		{
			PlayAnim(0);
		}
	}

	public void SetSkeletonGraphic(Component skeletonGraphic)
	{
		if ((Object)(object)mSkeletonGraphic != (Object)null)
		{
			DeregisterSkeletonEvent();
		}
		mSkeletonGraphic = skeletonGraphic;
		RegisterSkeletonEvent();
	}

	private void PlayAnim(int dataIdx)
	{
		if (dataIdx <= mAnimDataList.Count - 1)
		{
			AppearanceAnimData curAnimData = GetCurAnimData();
			mIdx = dataIdx;
			AppearanceAnimData curAnimData2 = GetCurAnimData();
			OnAnimStart?.Invoke(curAnimData2.AnimName);
			PlayAnim(curAnimData2, curAnimData);
		}
	}

	private void PlayAnim(AppearanceAnimData data, AppearanceAnimData preData)
	{
		IPartnerSequenceAnimationState animationState = Graphic.AnimationState;
		IPartnerSequenceAnimation orLoadSpineAnimation = Graphic.GetOrLoadAnimation(data.AnimName);
		IPartnerSequenceTrack val = animationState.SetAnimation(0, orLoadSpineAnimation, data.LoopTimes < 0);
		if (data.LoopTimes - mLoopTimes == 1 && data.NextMixDuration != 0f && GetNextAnimData().Valid)
		{
			mEnterMixTimer = val.Animation.Duration * data.ExitTime;
		}
		if (preData.NextMixDuration != 0f)
		{
			val.MixTime = 0.001f;
			val.MixDuration = preData.NextMixDuration;
		}
		Graphic.UpdateAnimation();
	}

	private AppearanceAnimData GetCurAnimData()
	{
		return GetAnimData(mIdx);
	}

	private AppearanceAnimData GetNextAnimData()
	{
		return GetAnimData(mIdx + 1);
	}

	private AppearanceAnimData GetAnimData(int idx)
	{
		if (idx < 0 || idx >= mAnimDataList.Count)
		{
			return default;
		}
		return mAnimDataList[idx];
	}

	private void Stop()
	{
		IPartnerSequenceAnimationState animationState = Graphic.AnimationState;
		if (animationState != null)
		{
			animationState.ClearTrack(0);
		}
		mLoopTimes = 0;
		mIdx = -1;
		mEnterMixTimer = 0f;
	}
}

}
